∀ {Ω : Type u_1} {inst : Fintype Ω} {mass : Ω → ℝ} {mass_nonneg : ∀ (ω : Ω), 0 ≤ mass ω}
  {mass_sum : ∑ ω : Ω, mass ω = 1} {mass_1 : Ω → ℝ} {mass_nonneg_1 : ∀ (ω : Ω), 0 ≤ mass_1 ω}
  {mass_sum_1 : ∑ ω : Ω, mass_1 ω = 1},
  { mass := mass, mass_nonneg := mass_nonneg, mass_sum := mass_sum } =
      { mass := mass_1, mass_nonneg := mass_nonneg_1, mass_sum := mass_sum_1 } →
    mass = mass_1

∀ (Ω : Type u_4) [inst : Fintype Ω] [inst_1 : Nonempty Ω],
  RiffleLowerV2.Thinning.Compat.FiniteLaw.uniform Ω =
    { mass := fun (x : Ω) => 1 / ↑(Fintype.card Ω), mass_nonneg := ⋯, mass_sum := ⋯ }

∀ {α : Type u_1} [inst : DecidableEq α] (A : Finset α) {V : Finset α} {m : ℕ}
  (S : RiffleLowerV2.Thinning.Compat.Sample V m),
  (A ∩ ↑S).card ≤ (↑S).card → (↑S).card = m → ¬(A ∩ ↑S).card < m + 1 → False

∀ (p : RiffleLowerV2.Thinning.Compat.HypergeomParams),
  RiffleLowerV2.Thinning.Compat.HypergeomParams.markedComplement✝ p =
    { population := p.population, marked := p.population - p.marked, draws := p.draws, marked_le := ⋯, draws_le := ⋯ }

∀ (p : RiffleLowerV2.Thinning.Compat.HypergeomParams),
  RiffleLowerV2.Thinning.Compat.HypergeomParams.swapped✝ p =
    { population := p.population, marked := p.draws, draws := p.marked, marked_le := ⋯, draws_le := ⋯ }
